mapper.select:
SELECT id, user_id, role, content, created_at
FROM conversation
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT id, user_id, role, content, created_at
FROM conversation
WHERE user_id = #{userId}
  AND created_at >= #{date}
  AND created_at < #{date} + INTERVAL 1 DAY
ORDER BY id

SELECT id, user_id, role, content, created_at, session_id
FROM conversation
WHERE user_id = #{userId}
ORDER BY id ASC
LIMIT #{limit}

SELECT id, user_id, role, content, created_at, session_id
FROM conversation
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY id ASC

mapper.delete:
DELETE FROM conversation
WHERE user_id = #{userId}
  AND session_id = #{sessionId}

mapper.select:
SELECT id, user_id, role, content, created_at, session_id
FROM conversation
WHERE user_id = #{userId}
  AND session_id IS NULL
ORDER BY id ASC
LIMIT #{limit}

SELECT id, user_id, role, content, created_at, session_id
FROM conversation
WHERE user_id = #{userId}
  AND content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id DESC
LIMIT #{limit}
